oxy_webhelp_navlinks = {"mt_sc_shared_clusters-d39536e67451":{"topics":[{"title":"Shared cluster multitenancy","shortdesc":"<p class=\"shortdesc\">Shared cluster multitenancy lets a Managed Service Provider serve multiple clients         from a single <span class=\"ph\">Rubrik cluster<\/span> while still giving each client a fully dedicated <span class=\"ph\">RSC<\/span> tenant experience.<\/p>","href":"saas\/mt_sc_shared_cluster_multitenancy.html","attributes":{"data-id":"mt_sc_shared_cluster_multitenancy"},"menu":{"hasChildren":false},"tocID":"mt_sc_shared_cluster_multitenancy-d39536e67465","next":"mt_sc_shared_cluster_multitenancy-d39536e67465"},{"title":"Who can perform shared cluster tasks","shortdesc":"<p class=\"shortdesc\">Primary and tenant account users can perform different tasks on dedicated tenants         that share clusters.<\/p>","href":"saas\/mt_sc_primary_tenant_tasks.html","attributes":{"data-id":"mt_sc_primary_tenant_tasks"},"menu":{"hasChildren":false},"tocID":"mt_sc_primary_tenant_tasks-d39536e67504","topics":[]},{"title":"Assigning shared clusters to tenant accounts","shortdesc":"<p class=\"shortdesc\">Assign a Rubrik cluster to multiple tenant accounts to extend infrastructure         resources to more than one tenant while maintaining tenant data isolation.<\/p>","href":"saas\/mt_sc_assigning_shared_clusters.html","attributes":{"data-id":"mt_sc_assigning_shared_clusters"},"menu":{"hasChildren":false},"tocID":"mt_sc_assigning_shared_clusters-d39536e67515","topics":[]},{"title":"Preparing for offline data recovery","shortdesc":"<p class=\"shortdesc\">Create local user accounts for tenant administrators on shared clusters that you can         use for data recovery if <span class=\"ph\">RSC<\/span> becomes unavailable.<\/p>","href":"saas\/mt_sc_preparing_offline_data_recovery.html","attributes":{"data-id":"mt_sc_preparing_offline_data_recovery"},"menu":{"hasChildren":false},"tocID":"mt_sc_preparing_offline_data_recovery-d39536e67526","topics":[]},{"title":"Tenant workloads on shared clusters","shortdesc":"<p class=\"shortdesc\">Connecting tenant workloads to a multitenant shared cluster requires planning for network topology, firewall rules, and port access.<\/p>","href":"saas\/mt_sc_tenant_workloads_sc.html","attributes":{"data-id":"mt_sc_tenant_workloads_sc"},"menu":{"hasChildren":false},"tocID":"mt_sc_tenant_workloads_sc-d39536e67540","next":"mt_sc_tenant_workloads_sc-d39536e67540"},{"title":"Replication for shared clusters","shortdesc":"<p class=\"shortdesc\">Tenant account administrators can configure replication pairings when one or both         clusters in the pairing are shared clusters.<\/p>","href":"saas\/mt_sc_shared_cluster_replication.html","attributes":{"data-id":"mt_sc_shared_cluster_replication"},"menu":{"hasChildren":false},"tocID":"mt_sc_shared_cluster_replication-d39536e67584","next":"mt_sc_shared_cluster_replication-d39536e67584"},{"title":"Recovering data when <span class=\"ph\">RSC<\/span> is unavailable","shortdesc":"<p class=\"shortdesc\">When <span class=\"ph\">RSC<\/span> is unavailable, authorized Managed Service Provider (MSP) administrators can log in         directly to the Rubrik cluster UI to perform tenant-scoped recovery operations on behalf of         tenants.<\/p>","href":"saas\/mt_sc_recovering_sc_offline.html","attributes":{"data-id":"mt_sc_recovering_sc_offline"},"menu":{"hasChildren":false},"tocID":"mt_sc_recovering_sc_offline-d39536e67617","topics":[]}]}};